css:
.rm-t-minimal-mono{padding:0 0 50px;color:#1b1b1b;background:#ffffff;font-family:-apple-system,BlinkMacSystemFont,"PingFang SC","Microsoft YaHei","Helvetica Neue",Arial,sans-serif;}
.rm-t-minimal-mono .rm-head{padding:58px 62px 20px;border-bottom:2px solid #111111;}
.rm-t-minimal-mono .rm-name{font-size:42px;font-weight:700;line-height:1.05;letter-spacing:-.01em;color:#000000;}
.rm-t-minimal-mono .rm-role{margin:12px 0 0;font-size:12px;letter-spacing:.26em;color:#555555;}
.rm-t-minimal-mono .rm-contact{display:flex;flex-wrap:wrap;gap:6px 22px;margin:22px 0 0;grid-template-columns:none;}
.rm-t-minimal-mono .rm-c{display:inline-flex;align-items:baseline;gap:6px;}
.rm-t-minimal-mono .rm-k{font-size:9.5px;letter-spacing:.18em;color:#999999;}
.rm-t-minimal-mono .rm-v{font-size:12px;color:#222222;}
.rm-t-minimal-mono .rm-body{padding:0 62px;}
.rm-t-minimal-mono .rm-sec{margin-top:26px;}
.rm-t-minimal-mono .rm-sec-h{margin:0 0 12px;padding-bottom:7px;border-bottom:1px solid #111111;gap:0;}
.rm-t-minimal-mono .rm-sec-t{font-size:10.5px;font-weight:600;letter-spacing:.32em;color:#111111;}
.rm-t-minimal-mono .rm-item{margin-bottom:15px;}
.rm-t-minimal-mono .rm-item-t{font-size:14px;font-weight:600;letter-spacing:.01em;color:#0a0a0a;}
.rm-t-minimal-mono .rm-item-role{font-size:12px;color:#666666;}
.rm-t-minimal-mono .rm-date{font-size:10.5px;letter-spacing:.08em;color:#888888;}
.rm-t-minimal-mono .rm-item-sub{font-size:11.5px;color:#777777;}
.rm-t-minimal-mono .rm-edu-courses{font-size:11px;color:#777777;}
.rm-t-minimal-mono .rm-edu-courses .rm-k{font-size:9.5px;letter-spacing:.12em;color:#999999;}
.rm-t-minimal-mono .rm-bullets{padding-left:15px;}
.rm-t-minimal-mono .rm-bullets li{margin:3px 0;}
.rm-t-minimal-mono .rm-bullets li::marker{color:#bbbbbb;}
.rm-t-minimal-mono .rm-summary{font-size:12.5px;line-height:1.7;color:#333333;}
.rm-t-minimal-mono .rm-tags{gap:6px;}
.rm-t-minimal-mono .rm-tag{background:transparent;border:1px solid #d8d8d8;border-radius:2px;color:#444444;font-size:11px;padding:1px 8px;}
.rm-t-minimal-mono .rm-skill-row{grid-template-columns:92px minmax(0,1fr);gap:10px;margin-bottom:7px;}
.rm-t-minimal-mono .rm-skill-k{font-size:10px;font-weight:600;letter-spacing:.16em;color:#999999;}
.rm-t-minimal-mono .rm-award-row{margin-bottom:6px;}
.rm-t-minimal-mono .rm-award-t{font-size:12.5px;color:#111111;}
.rm-t-minimal-mono .rm-award-desc{font-size:11.5px;color:#777777;}
.rm-t-minimal-mono .rm-sec-campus .rm-item{margin-bottom:9px;}
.rm-t-minimal-mono .rm-sec-hobbies .rm-tags{padding-left:0;}
